class MyCalendarThree {
    private static class Node {
        Node left;
        Node right;
        int add;
        int max;
    }

    private final Node root = new Node();

    public MyCalendarThree() {}

    public int book(int start, int end) {
        update(root, 0, 1_000_000_000, start, end - 1, 1);
        return root.max;
    }

    private void update(Node node, int left, int right, int ql, int qr, int delta) {
        if (qr < left || right < ql) return;
        if (ql <= left && right <= qr) {
            node.add += delta;
            node.max += delta;
            return;
        }

        int mid = left + (right - left) / 2;
        if (ql <= mid) {
            if (node.left == null) node.left = new Node();
            update(node.left, left, mid, ql, qr, delta);
        }
        if (qr > mid) {
            if (node.right == null) node.right = new Node();
            update(node.right, mid + 1, right, ql, qr, delta);
        }

        int leftMax = node.left == null ? 0 : node.left.max;
        int rightMax = node.right == null ? 0 : node.right.max;
        node.max = node.add + Math.max(leftMax, rightMax);
    }
}

class MyCalendarThree {
    private final java.util.List<int[]> bookings = new java.util.ArrayList<>();

    public MyCalendarThree() {}

    public int book(int start, int end) {
        bookings.add(new int[] {start, end});

        java.util.TreeSet<Integer> points = new java.util.TreeSet<>();
        for (int[] booking : bookings) {
            points.add(booking[0]);
            points.add(booking[1]);
        }

        java.util.Map<Integer, Integer> index = new java.util.HashMap<>();
        int next = 0;
        for (int point : points) {
            index.put(point, next++);
        }

        int[] diff = new int[points.size() + 1];
        for (int[] booking : bookings) {
            diff[index.get(booking[0])]++;
            diff[index.get(booking[1])]--;
        }

        int active = 0;
        int best = 0;
        for (int change : diff) {
            active += change;
            best = Math.max(best, active);
        }
        return best;
    }
}

class MyCalendarThree {
    private final java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
    private int best = 0;

    public MyCalendarThree() {
        counts.put(0, 0);
        counts.put(1_000_000_000, 0);
    }

    public int book(int start, int end) {
        split(start);
        split(end);
        for (java.util.Map.Entry<Integer, Integer> entry = counts.ceilingEntry(start);
             entry != null && entry.getKey() < end;
             entry = counts.higherEntry(entry.getKey())) {
            int next = entry.getValue() + 1;
            counts.put(entry.getKey(), next);
            best = Math.max(best, next);
        }
        return best;
    }

    private void split(int time) {
        java.util.Map.Entry<Integer, Integer> floor = counts.floorEntry(time);
        if (floor != null && floor.getKey() != time) {
            counts.put(time, floor.getValue());
        }
    }
}

